import biome from "./biome.json" with { type: "json" };

const { formatter, javascript, json } = biome;

/** Formats this project with the settings of the imported JSON configuration. */
export default {
    ignore: [
        ".cache",
        ".git",
        ".yarn",
        "coverage",
        // generated by project.sh, and ignored by git
        "docker-compose.yml",
        "node_modules",
        "packages/*/bin",
        "shared/*/bin",
        "yarn.lock",
        "*.tsbuildinfo",
    ],
    rules: {
        ...formatter,
        javascript: javascript.formatter,
        json: json.formatter,
    },
};
